static std::wstring Join(const std::wstring&a,const std::wstring&b){return a+L"\\"+b;}
static long long UnixNow(){return std::chrono::duration_cast<std::chrono::seconds>(std::chrono::system_clock::now().time_since_epoch()).count();}
static int Clamp(int x,int a,int b){return std::max(a,std::min(b,x));}
static bool ClassStarts(HWND h,const wchar_t* prefix){wchar_t c[256]{};GetClassNameW(h,c,255);return _wcsnicmp(c,prefix,wcslen(prefix))==0;}
static RECT MonitorRect(POINT p,bool work){HMONITOR m=MonitorFromPoint(p,MONITOR_DEFAULTTONEAREST);MONITORINFO i{sizeof(i)};GetMonitorInfoW(m,&i);return work?i.rcWork:i.rcMonitor;}
static RECT PrimaryWork(){POINT p{};MONITORINFO i{sizeof(i)};GetMonitorInfoW(MonitorFromPoint(p,MONITOR_DEFAULTTOPRIMARY),&i);return i.rcWork;}
static std::wstring ProcessPath(HWND h){DWORD pid{};GetWindowThreadProcessId(h,&pid);HANDLE p=OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,pid);if(!p)return{};std::vector<wchar_t>b(32768);DWORD n=(DWORD)b.size();BOOL ok=QueryFullProcessImageNameW(p,0,b.data(),&n);CloseHandle(p);return ok?std::wstring(b.data(),n):L"";}
static std::wstring Lower(std::wstring s){std::transform(s.begin(),s.end(),s.begin(),towlower);return s;}
static bool IsIgnored(HWND h){return ClassStarts(h,L"Fences");}
static bool IsShell(HWND h){return ClassStarts(h,L"Progman")||ClassStarts(h,L"WorkerW")||ClassStarts(h,L"Shell_TrayWnd")||ClassStarts(h,L"Shell_SecondaryTrayWnd");}
static bool IsCloaked(HWND h){DWORD v=0;return SUCCEEDED(DwmGetWindowAttribute(h,DWMWA_CLOAKED,&v,sizeof(v)))&&v;}
static RECT Bounds(HWND h){RECT r{};if(FAILED(DwmGetWindowAttribute(h,DWMWA_EXTENDED_FRAME_BOUNDS,&r,sizeof(r))))GetWindowRect(h,&r);return r;}
static bool RectContains(const RECT&r,POINT p){return p.x>=r.left&&p.x<r.right&&p.y>=r.top&&p.y<r.bottom;}
static bool DesktopListBlankAt(HWND h,POINT p){IAccessible* list=nullptr;if(FAILED(AccessibleObjectFromWindow(h,(DWORD)OBJID_CLIENT,IID_IAccessible,(void**)&list))||!list)return false;VARIANT hit{};VariantInit(&hit);HRESULT hr=list->accHitTest(p.x,p.y,&hit);bool blank=false;if(SUCCEEDED(hr)){if(hit.vt==VT_EMPTY)blank=true;else if(hit.vt==VT_I4&&hit.lVal==CHILDID_SELF)blank=true;else if(hit.vt==VT_DISPATCH&&hit.pdispVal){IAccessible* child=nullptr;if(SUCCEEDED(hit.pdispVal->QueryInterface(IID_IAccessible,(void**)&child))&&child){VARIANT self{};self.vt=VT_I4;self.lVal=CHILDID_SELF;VARIANT role{};VariantInit(&role);if(SUCCEEDED(child->get_accRole(self,&role))&&role.vt==VT_I4)blank=role.lVal==(LONG)ROLE_SYSTEM_LIST||role.lVal==(LONG)ROLE_SYSTEM_PANE||role.lVal==(LONG)ROLE_SYSTEM_WINDOW;VariantClear(&role);child->Release();}}}VariantClear(&hit);list->Release();return blank;}
static bool IsGamePath(const std::wstring& p){std::wstring s=Lower(p);if(s.find(L"\\steamapps\\common\\wallpaper_engine\\")!=s.npos||s.find(L"\\steamapps\\common\\lossless scaling\\")!=s.npos||s.find(L"\\steamapps\\common\\steamvr\\")!=s.npos)return false;return s.find(L"\\steamapps\\common\\")!=s.npos||s.find(L"\\epic games\\")!=s.npos||s.find(L"\\gog games\\")!=s.npos||s.find(L"\\xboxgames\\")!=s.npos;}
static bool ValidAlarmTime(const std::wstring& s){auto digit=[](wchar_t c){return c>=L'0'&&c<=L'9';};if(s.size()!=5||!digit(s[0])||!digit(s[1])||s[2]!=L':'||!digit(s[3])||!digit(s[4]))return false;int hour=(s[0]-L'0')*10+(s[1]-L'0'),minute=(s[3]-L'0')*10+(s[4]-L'0');return hour<24&&minute<60;}
static void PlayEffect(int volume){volume=Clamp(volume,0,100);std::thread([volume](){constexpr int rate=22050,samples=5512;std::vector<BYTE> data(samples);double amp=volume*1.1;for(int i=0;i<samples;++i){double hz=i<samples/2?740.0:988.0;data[i]=(BYTE)Clamp((int)(128+std::sin(6.283185307*hz*i/rate)*amp),0,255);}WAVEFORMATEX fmt{WAVE_FORMAT_PCM,1,rate,rate,1,8,0};HWAVEOUT out{};if(waveOutOpen(&out,WAVE_MAPPER,&fmt,0,0,CALLBACK_NULL)!=MMSYSERR_NOERROR)return;WAVEHDR hdr{};hdr.lpData=(LPSTR)data.data();hdr.dwBufferLength=(DWORD)data.size();waveOutPrepareHeader(out,&hdr,sizeof(hdr));waveOutWrite(out,&hdr,sizeof(hdr));while(!(hdr.dwFlags&WHDR_DONE))Sleep(10);waveOutUnprepareHeader(out,&hdr,sizeof(hdr));waveOutClose(out);}).detach();}

