    case WM_COMMAND:{int id=LOWORD(w);if(id==ID_SAVE){readActivity();readSettingsControls();}else if(id==ID_POMODORO){readActivity();readSettingsControls();if(pomodoro_)stopPomodoro();else startPomodoro();}else if(id==ID_ROLL){int sel=(int)SendDlgItemMessageW(h,ID_DICE,CB_GETCURSEL,0,0);int sides[]={3,4,6,10,20,100};sel=Clamp(sel,0,5);int result=1+(int)(rng_()%sides[sel]);vx_=0;mode_=Mode::Normal;setPose(Pose::Dice);showBubble(L"1d"+std::to_wstring(sides[sel])+L" → "+std::to_wstring(result)+L"！");scheduleAction(4,5);}else if(id==ID_EXIT){if(MessageBoxW(h,L"ちび堕ふるを終了しますか？",L"アプリを終了",MB_YESNO|MB_ICONQUESTION)==IDYES)DestroyWindow(pet_);}return 0;}
