void App::setAutoStart(bool enabled){HKEY key{};if(RegCreateKeyExW(HKEY_CURRENT_USER,L"Software\\Microsoft\\Windows\\CurrentVersion\\Run",0,nullptr,0,KEY_SET_VALUE,nullptr,&key,nullptr)!=ERROR_SUCCESS)return;if(enabled){std::wstring value=L"\""+Join(root_,L"DesktopChibiFriend.exe")+L"\"";RegSetValueExW(key,L"DesktopChibiFriend",0,REG_SZ,(BYTE*)value.c_str(),(DWORD)((value.size()+1)*sizeof(wchar_t)));}else RegDeleteValueW(key,L"DesktopChibiFriend");RegCloseKey(key);}
